//! The icon set Notra's components use, embedded as SVG with `currentColor` paint so
//! either renderer can tint them. Generated by `scripts/gen-icons.mjs` from
//! `assets/icons`: Lucide (ISC), Hugeicons free icons (`huge-*`) and brand marks.

/// An embedded SVG icon.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Icon {
    ArrowDown,
    ArrowRight,
    ArrowUp,
    Bold,
    Check,
    ChevronDown,
    ChevronLeft,
    ChevronRight,
    ChevronsUpDown,
    CircleCheck,
    Circle,
    Code,
    Copy,
    Dices,
    Download,
    ExternalLink,
    Globe,
    HugeArrowLeft01,
    HugeArrowRight01,
    HugeInformationCircle,
    HugeSearch,
    HugeUnfoldMore,
    Info,
    Italic,
    Link,
    List,
    LoaderCircle,
    LockKeyhole,
    Mail,
    Map,
    Maximize,
    Mic,
    OctagonX,
    Pencil,
    Play,
    Plus,
    Quote,
    RotateCcw,
    Search,
    Settings,
    Square,
    ThumbsDown,
    ThumbsUp,
    Timer,
    Trash2,
    TriangleAlert,
    Underline,
    Users,
    X,
    ZoomIn,
    ZoomOut,
}

